import { LineContentCodec } from "../database/compression/zstd";
import { bytesSource } from "../database/sqlite/lazy/byte-source";
import { SqliteFile } from "../database/sqlite/lazy/sqlite-file";

/*
 * The worker's start-up self-check (the offline E2E test reads its result): proves, in THIS
 * environment (file://, CSP, a classic worker), that the two engines the tool really reads with
 * start — our lazy SQLite reader and the zstd WASM decoder. It used to start sql.js for this, which
 * nothing else in the app uses and which was half of the HTML file (architecture review #1).
 */

/** A 1 KiB SQLite file (page size 512): table probe(v TEXT) with one row, "בדיקת sqlite". */
const SQLITE_PROBE_B64 = "";

/** A tiny zstd frame of "בדיקת zstd". */
const ZSTD_PROBE = new Uint8Array([40, 181, 47, 253, 32, 15, 121, 0, 0, 215, 145, 215, 147, 215, 153, 215, 167, 215, 170, 32, 122, 115, 116, 100]);

export async function selfCheck(): Promise<{ sqlite: string; zstd: string }> {
  const bin = atob(SQLITE_PROBE_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const file = await SqliteFile.open(bytesSource(bytes));
  const table = await file.table("probe");
  let sqlite = "";
  if (table) for await (const row of file.scan(table)) sqlite = String(row.values[0] ?? "");
  return { sqlite, zstd: new LineContentCodec([]).decode(ZSTD_PROBE) ?? "" };
}
